manifest['scenarios']=[dict(id='budget-choices',title='Explore the illustrative memory budget',description='Change weight storage and cache allowance while capacity stays 12 GiB, workspace 1 GiB and reserve 2 GiB. No model is executed.',variables=[dict(id='weights',label='Weight representation',options=['BF16','toy Q4']),dict(id='cache',label='Cache allowance',options=['2 GiB','8 GiB'])],cases=[])]
for weights,w in [('BF16',16_000_000_000/(2**30)),('toy Q4',4_500_000_000/(2**30))]:
 for cache,c in [('2 GiB',2),('8 GiB',8)]:
  total=w+c+3
  manifest['scenarios'][0]['cases'].append(dict(when=dict(weights=weights,cache=cache),outcome=('Fits' if total<=12 else 'Exceeds capacity')+f': {total:.3f} GiB including reserve',narrative='Weight payload plus stated metadata, cache allowance, workspace and reserve; actual backend peaks remain unmeasured.',active_entity_ids=[],claim_ids=['numeric-references']))
outputs=json.loads((ROOT/'evidence/reference-outputs.json').read_text())
lessons=sorted((ROOT/'lessons').glob('*.md')); examples=sorted((ROOT/'examples').iterdir())
assert len(lessons)==len(examples)==len(qa)==24
for lesson,example,(ident,question,answer,rubric) in zip(lessons,examples,qa):
 body=lesson.read_text(); title=body.splitlines()[0].removeprefix('## ')
 obj='explain-'+ident;practice=ident+'-transfer'
 manifest['objectives'].append(dict(id=obj,text=title))
 manifest['practice'].append(dict(id=practice,question=question,answer=answer,rubric=rubric,objective_ids=[obj],claim_ids=['numeric-references'] if ident not in ['scaffold','compatibility','handoff'] else []))
 manifest['chapters'].append(dict(id=ident,title=title,content_path='lessons/'+lesson.name,objective_ids=[obj],diagram_ids=[],table_ids=[],scenario_ids=['budget-choices'] if ident=='memory' else [],practice_ids=[practice]))
 lang='cpp' if example.suffix=='.cpp' else 'python'
 manifest['examples'].append(dict(id='reference-'+ident,language=lang,path='examples/'+example.name,purpose=title+'; complete authored teaching reference, not model inference',expected_output=outputs[example.name]))
 if '{{example}}' in body:
  listing='[Download the complete reference](examples/'+example.name+')\n\n```'+lang+'\n'+example.read_text().rstrip()+'\n```'
  body=body.replace('{{example}}',listing)
 if '{{run}}' in body:
  command=('c++ -std=c++20 -O2 -Wall -Wextra -Werror -pedantic '+example.name+' -o pack_int4\n./pack_int4' if lang=='cpp' else 'python3 '+example.name)
  body=body.replace('{{run}}','From the scratch directory containing that file, run:\n\n```bash\n'+command+'\n```\n\nExpected checked output (JSON formatting may differ):\n\n```json\n'+json.dumps(outputs[example.name],indent=2,ensure_ascii=False)+'\n```')
 if '{{actual_source}}' in body:
  listing=''
  for rel in ['src/core/config.py','src/core/workflow.py','src/utils/commands.py','src/document_assistant.py']:
   listing+='**Existing `'+rel+'`:**\n\n```python\n'+(PROJECT/rel).read_text().rstrip()+'\n```\n\n'
  body=body.replace('{{actual_source}}',listing.rstrip())
 lesson.write_text(body)
